//! Table detail for the Structure, Index, Triggers and DDL views, and the
//! typed structure changes a driver turns into DDL (docs/10 §3).

/// How a column's value is produced by the server.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum Generated {
    /// An ordinary column (it may still have a default).
    #[default]
    No,
    /// `GENERATED ALWAYS AS IDENTITY`.
    IdentityAlways,
    /// `GENERATED BY DEFAULT AS IDENTITY`.
    IdentityByDefault,
    /// `GENERATED ALWAYS AS (expression) STORED`; the expression is the default.
    Stored,
}

/// One column with everything the Structure grid and the DDL need.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct ColumnDetail {
    /// Column name.
    pub name: String,
    /// Formatted type, e.g. `character varying(40)`.
    pub data_type: String,
    /// `false` for `NOT NULL` columns.
    pub nullable: bool,
    /// Default expression, or the generation expression of a stored column.
    pub default: Option<String>,
    /// Identity or generated-column kind.
    pub generated: Generated,
    /// Comment, when set.
    pub comment: Option<String>,
}

/// Kind of a table constraint.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ConstraintKind {
    /// `PRIMARY KEY`.
    Primary,
    /// `UNIQUE`.
    Unique,
    /// `CHECK`.
    Check,
    /// `FOREIGN KEY`.
    Foreign,
    /// `EXCLUDE`.
    Exclusion,
}

/// The referenced side of a foreign key.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct ForeignTarget {
    /// Referenced schema.
    pub schema: String,
    /// Referenced table.
    pub table: String,
    /// Referenced columns, in key order.
    pub columns: Vec<String>,
}

/// One table constraint.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ConstraintDetail {
    /// Constraint name.
    pub name: String,
    /// Constraint kind.
    pub kind: ConstraintKind,
    /// Server-formatted definition, e.g. `CHECK ((price > 0))`.
    pub definition: String,
    /// Constrained columns, in key order (empty for expression-only checks).
    pub columns: Vec<String>,
    /// Referenced table of a foreign key.
    pub references: Option<ForeignTarget>,
}

/// One index with its full definition.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct IndexDetail {
    /// Index name.
    pub name: String,
    /// Access method, e.g. `btree`.
    pub method: String,
    /// Enforces uniqueness.
    pub unique: bool,
    /// Backs the primary key.
    pub primary: bool,
    /// Backs a constraint (primary key, unique or exclusion).
    pub constraint: bool,
    /// Key columns or expressions, comma-separated.
    pub columns: String,
    /// `INCLUDE` columns.
    pub include: Vec<String>,
    /// Partial-index predicate.
    pub predicate: Option<String>,
    /// Comment, when set.
    pub comment: Option<String>,
    /// `CREATE INDEX …` as the server prints it.
    pub definition: String,
}

/// When a trigger fires.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TriggerTiming {
    /// `BEFORE`.
    Before,
    /// `AFTER`.
    After,
    /// `INSTEAD OF`.
    InsteadOf,
}

/// An event a trigger fires on.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TriggerEvent {
    /// `INSERT`.
    Insert,
    /// `UPDATE`.
    Update,
    /// `DELETE`.
    Delete,
    /// `TRUNCATE`.
    Truncate,
}

/// One user trigger.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct TriggerDetail {
    /// Trigger name.
    pub name: String,
    /// When it fires.
    pub timing: TriggerTiming,
    /// Events it fires on.
    pub events: Vec<TriggerEvent>,
    /// `FOR EACH ROW` (otherwise statement level).
    pub row_level: bool,
    /// Schema-qualified trigger function.
    pub function: String,
    /// Not disabled (`tgenabled <> 'D'`).
    pub enabled: bool,
    /// `CREATE TRIGGER …` as the server prints it.
    pub definition: String,
}

/// Kind of the browsed relation.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum RelationKind {
    /// Ordinary table.
    #[default]
    Table,
    /// Partitioned table.
    PartitionedTable,
    /// View.
    View,
    /// Materialized view.
    MaterializedView,
    /// Foreign table.
    ForeignTable,
}

/// Sizes, estimate and comment of a relation.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct TableInfo {
    /// Relation kind.
    pub kind: RelationKind,
    /// Planner estimate; `None` when never analysed.
    pub row_estimate: Option<u64>,
    /// Table, TOAST and indexes (`pg_total_relation_size`).
    pub total_bytes: u64,
    /// Main fork (`pg_relation_size`).
    pub data_bytes: u64,
    /// All indexes (`pg_indexes_size`).
    pub index_bytes: u64,
    /// Comment, when set.
    pub comment: Option<String>,
    /// View query of a view or materialized view.
    pub view_definition: Option<String>,
    /// `PARTITION BY` clause body of a partitioned table, e.g. `RANGE (day)`.
    pub partition_key: Option<String>,
}

/// Everything the Structure, Index, Triggers and DDL views show.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct TableDetail {
    /// Columns in ordinal order.
    pub columns: Vec<ColumnDetail>,
    /// Constraints: primary key, unique, check, foreign key, exclusion.
    pub constraints: Vec<ConstraintDetail>,
    /// Indexes ordered by name.
    pub indexes: Vec<IndexDetail>,
    /// User triggers ordered by name.
    pub triggers: Vec<TriggerDetail>,
    /// `None` when the relation does not exist.
    pub info: Option<TableInfo>,
}

/// A column default: dropped, a quoted text literal or a raw SQL expression.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum DefaultValue {
    /// No default (`DROP DEFAULT`).
    None,
    /// A string literal the server casts to the column type.
    Literal(String),
    /// A SQL expression written by the user, e.g. `now()`.
    Expression(String),
}

/// Index access methods that may be created from the UI.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum IndexMethod {
    /// B-tree.
    Btree,
    /// Hash.
    Hash,
    /// `GiST`.
    Gist,
    /// GIN.
    Gin,
    /// BRIN.
    Brin,
    /// SP-GiST.
    Spgist,
}

/// A column to add.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct NewColumn {
    /// Column name.
    pub name: String,
    /// Type as SQL type syntax, e.g. `varchar(40)`.
    pub data_type: String,
    /// `false` adds `NOT NULL`.
    pub nullable: bool,
    /// Default value.
    pub default: DefaultValue,
    /// Comment.
    pub comment: Option<String>,
}

/// An index to create.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct NewIndex {
    /// Index name; the server picks one when `None`.
    pub name: Option<String>,
    /// Key columns (final names), in order.
    pub columns: Vec<String>,
    /// `UNIQUE`.
    pub unique: bool,
    /// Access method.
    pub method: IndexMethod,
}

/// One staged structure change; columns are named by their current name.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum SchemaChange {
    /// `ALTER TABLE … RENAME TO`.
    RenameTable(String),
    /// `COMMENT ON TABLE`; `None` removes it.
    TableComment(Option<String>),
    /// `RENAME COLUMN column TO name`.
    RenameColumn {
        /// Current name.
        column: String,
        /// New name.
        name: String,
    },
    /// `ALTER COLUMN … TYPE`.
    ColumnType {
        /// Current name.
        column: String,
        /// New type as SQL type syntax.
        data_type: String,
    },
    /// `SET` / `DROP NOT NULL`.
    ColumnNullable {
        /// Current name.
        column: String,
        /// `true` drops `NOT NULL`.
        nullable: bool,
    },
    /// `SET` / `DROP DEFAULT`.
    ColumnDefault {
        /// Current name.
        column: String,
        /// New default.
        default: DefaultValue,
    },
    /// `COMMENT ON COLUMN`; `None` removes it.
    ColumnComment {
        /// Current name.
        column: String,
        /// New comment.
        comment: Option<String>,
    },
    /// `ADD COLUMN`.
    AddColumn(NewColumn),
    /// `DROP COLUMN` (current name).
    DropColumn(String),
    /// `CREATE INDEX`.
    CreateIndex(NewIndex),
    /// `DROP INDEX` (name).
    DropIndex(String),
}
